-- Schema adapted from XXL-JOB 3.1.1 official tables_xxl_job.sql (GPL-3.0).
CREATE DATABASE IF NOT EXISTS xxl_job CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE xxl_job;
CREATE TABLE xxl_job_info(id INT AUTO_INCREMENT PRIMARY KEY,job_group INT NOT NULL,job_desc VARCHAR(255) NOT NULL,add_time DATETIME,update_time DATETIME,author VARCHAR(64),alarm_email VARCHAR(255),schedule_type VARCHAR(50) NOT NULL DEFAULT 'NONE',schedule_conf VARCHAR(128),misfire_strategy VARCHAR(50) NOT NULL DEFAULT 'DO_NOTHING',executor_route_strategy VARCHAR(50),executor_handler VARCHAR(255),executor_param VARCHAR(512),executor_block_strategy VARCHAR(50),executor_timeout INT NOT NULL DEFAULT 0,executor_fail_retry_count INT NOT NULL DEFAULT 0,glue_type VARCHAR(50) NOT NULL,glue_source MEDIUMTEXT,glue_remark VARCHAR(128),glue_updatetime DATETIME,child_jobid VARCHAR(255),trigger_status TINYINT NOT NULL DEFAULT 0,trigger_last_time BIGINT NOT NULL DEFAULT 0,trigger_next_time BIGINT NOT NULL DEFAULT 0);
CREATE TABLE xxl_job_log(id BIGINT AUTO_INCREMENT PRIMARY KEY,job_group INT NOT NULL,job_id INT NOT NULL,executor_address VARCHAR(255),executor_handler VARCHAR(255),executor_param VARCHAR(512),executor_sharding_param VARCHAR(20),executor_fail_retry_count INT NOT NULL DEFAULT 0,trigger_time DATETIME,trigger_code INT NOT NULL,trigger_msg TEXT,handle_time DATETIME,handle_code INT NOT NULL,handle_msg TEXT,alarm_status TINYINT NOT NULL DEFAULT 0,INDEX(trigger_time),INDEX(handle_code),INDEX(job_id,job_group));
CREATE TABLE xxl_job_log_report(id INT AUTO_INCREMENT PRIMARY KEY,trigger_day DATETIME UNIQUE,running_count INT NOT NULL DEFAULT 0,suc_count INT NOT NULL DEFAULT 0,fail_count INT NOT NULL DEFAULT 0,update_time DATETIME);
CREATE TABLE xxl_job_logglue(id INT AUTO_INCREMENT PRIMARY KEY,job_id INT NOT NULL,glue_type VARCHAR(50),glue_source MEDIUMTEXT,glue_remark VARCHAR(128),add_time DATETIME,update_time DATETIME);
CREATE TABLE xxl_job_registry(id INT AUTO_INCREMENT PRIMARY KEY,registry_group VARCHAR(50) NOT NULL,registry_key VARCHAR(255) NOT NULL,registry_value VARCHAR(255) NOT NULL,update_time DATETIME,UNIQUE(registry_group,registry_key,registry_value));
CREATE TABLE xxl_job_group(id INT AUTO_INCREMENT PRIMARY KEY,app_name VARCHAR(64) NOT NULL,title VARCHAR(12) NOT NULL,address_type TINYINT NOT NULL DEFAULT 0,address_list TEXT,update_time DATETIME);
CREATE TABLE xxl_job_user(id INT AUTO_INCREMENT PRIMARY KEY,username VARCHAR(50) NOT NULL UNIQUE,password VARCHAR(50) NOT NULL,role TINYINT NOT NULL,permission VARCHAR(255));
CREATE TABLE xxl_job_lock(lock_name VARCHAR(50) PRIMARY KEY);
